import{_ as t,o as d,c as r,Q as o}from"./chunks/framework.ec6aa115.js";const _=JSON.parse('{"title":"从前端到全栈：24 篇业务开发实战教程","description":"面向已有 Node BFF 和 Java Spring Boot 经验的前端开发者，用 TeamFlow 团队工单平台学习业务建模、数据库、事务、权限、测试与运行交付。","frontmatter":{"title":"从前端到全栈：24 篇业务开发实战教程","description":"面向已有 Node BFF 和 Java Spring Boot 经验的前端开发者，用 TeamFlow 团队工单平台学习业务建模、数据库、事务、权限、测试与运行交付。"},"headers":[],"relativePath":"guide/fullstack-course/index.md","filePath":"guide/fullstack-course/index.md","lastUpdated":1792489633000}'),e={name:"guide/fullstack-course/index.md"},s=o('<h1 id="从前端到全栈-24-篇业务开发实战教程" tabindex="-1">从前端到全栈：24 篇业务开发实战教程 <a class="header-anchor" href="#从前端到全栈-24-篇业务开发实战教程" aria-label="Permalink to &quot;从前端到全栈：24 篇业务开发实战教程&quot;">​</a></h1><p>面向已有 <strong>Node BFF 和 Java Spring Boot 经验</strong>的前端开发者，通过 TeamFlow 团队工单平台，逐步具备独立交付和维护业务系统的能力。</p><p>技术主线是 <strong>React / TypeScript → Spring Boot 模块化单体 → PostgreSQL</strong>。前期先建立完整的业务与数据保证，后半程再通过页面聚合、会话适配等具体需求引入 Node BFF，并与 Java 实现对照。</p><h2 id="已发布文章" tabindex="-1">已发布文章 <a class="header-anchor" href="#已发布文章" aria-label="Permalink to &quot;已发布文章&quot;">​</a></h2><ul><li><a href="./01-from-bff-to-business-backend">系列总纲与第 01 篇：从“把接口接通”到“对业务结果负责”</a></li><li><a href="/vitePress-blob/fullstack-course/fullstack-series-01.html">下载完整 HTML 教程</a></li></ul><p>第 01 篇包含完整学习路线、24 篇课程安排、创建工单案例、职责场景练习，以及 6 道选择题的题目、答案和解析。第 02—24 篇为后续课程规划。</p><h2 id="系列规划" tabindex="-1">系列规划 <a class="header-anchor" href="#系列规划" aria-label="Permalink to &quot;系列规划&quot;">​</a></h2><table><thead><tr><th>篇</th><th>主题</th><th>本篇交付成果</th></tr></thead><tbody><tr><td><strong>01</strong></td><td>从前端/BFF 走向完整业务交付</td><td>创建工单的职责、规则、失败路径与验收清单</td></tr><tr><td><strong>02</strong></td><td>跑通第一条真实业务链路</td><td>React → Spring Boot → PostgreSQL 的可运行功能</td></tr><tr><td><strong>03</strong></td><td>API 契约、校验与错误处理</td><td>稳定的请求、响应、状态码和错误结构</td></tr><tr><td><strong>04</strong></td><td>业务建模与关系建模</td><td>用户、团队、成员、项目、工单的数据模型</td></tr><tr><td><strong>05</strong></td><td>SQL、关联查询与数据库迁移</td><td>可重复建库、升级、初始化和查询</td></tr><tr><td><strong>06</strong></td><td>Spring Boot 的业务代码组织</td><td>按业务模块组织 Controller、Service、Repository</td></tr><tr><td><strong>07</strong></td><td>事务与业务一致性</td><td>工单和审计记录共同提交、共同回滚</td></tr><tr><td><strong>08</strong></td><td>并发、幂等与状态转换</td><td>两人同时编辑、超时重试和非法状态变更的处理</td></tr><tr><td><strong>09</strong></td><td>身份认证与登录态</td><td>接入身份系统，理解会话与令牌生命周期</td></tr><tr><td><strong>10</strong></td><td>授权、RBAC 与租户隔离</td><td>资源级权限判断和全链路租户作用域</td></tr><tr><td><strong>11</strong></td><td>Web 安全与输入边界</td><td>CSRF、XSS、注入、CORS 在项目中的处理</td></tr><tr><td><strong>12</strong></td><td>稳定的前后端交互</td><td>加载、取消、重试、乐观更新和冲突恢复</td></tr><tr><td><strong>13</strong></td><td>有意义的自动化测试</td><td>真实数据库、权限拒绝、事务回滚和关键并发测试</td></tr><tr><td><strong>14</strong></td><td>SQL 性能、索引与分页</td><td>读执行计划、定位慢查询、选择合适分页方式</td></tr><tr><td><strong>15</strong></td><td>Redis 缓存与一致性</td><td>缓存一个适合的查询，定义失效与陈旧容忍度</td></tr><tr><td><strong>16</strong></td><td>异步任务、Outbox 与可靠重试</td><td>持久化任务、重试、失败状态和重复消费处理</td></tr><tr><td><strong>17</strong></td><td>文件上传与批量导入导出</td><td>上传权限、逐行校验、错误报告和受控下载</td></tr><tr><td><strong>18</strong></td><td>Node BFF 的合理应用</td><td>聚合工单概览；对照 Node 与 Java 的用例组织</td></tr><tr><td><strong>19</strong></td><td>日志、指标与链路追踪</td><td>从页面报错追到服务、SQL 或后台任务</td></tr><tr><td><strong>20</strong></td><td>容器、配置与应用生命周期</td><td>可复现启动、健康检查、配置分离和正常退出</td></tr><tr><td><strong>21</strong></td><td>反向代理、域名与 HTTPS</td><td>完整访问链路，以及 Cookie、代理和跨域排障</td></tr><tr><td><strong>22</strong></td><td>CI/CD 与数据库变更</td><td>构建、校验、发布和向前兼容的数据库升级</td></tr><tr><td><strong>23</strong></td><td>压测、备份恢复与故障处理</td><td>一次有目标的压测和一次真实恢复演练</td></tr><tr><td><strong>24</strong></td><td>项目验收与全栈能力展示</td><td>可运行项目、设计说明、运行手册和成果表达</td></tr></tbody></table><p>每篇围绕具体业务问题，包含概念与前端经验的对应、工程案例、代码或数据模型、互动练习、自测题及解析，以及课后实践和验收条件。</p><h2 id="内容与阅读" tabindex="-1">内容与阅读 <a class="header-anchor" href="#内容与阅读" aria-label="Permalink to &quot;内容与阅读&quot;">​</a></h2><p>文章完整原文与 HTML、Vue 组件一同保存在仓库中。网页直接呈现全文，保留标题层级、段落、列表、表格、代码、题目、答案与解析；场景切换和测验评分由 Vue 接管。独立 HTML 文件使用同一正文生成，可以下载后打开阅读。</p>',11),n=[s];function a(g,i,l,c,h,p){return d(),r("div",null,n)}const S=t(e,[["render",a]]);export{_ as __pageData,S as default};
